<script lang="ts">
 import {onMount,untrack} from 'svelte';
 import {page} from '$app/state';
 import {api,readLocal} from '#lib/client';
 import {money,type City} from '#lib/catalog';
 import {conversionCurrencies,preferredCurrency} from '#lib/conversion-currencies';
 import {basket,defaultCounts,cityBasket,sumRows,validateComparison,type ComparisonConfig} from '#lib/comparison';
 import type {Offer} from '#lib/research-offers';
 let {data}=$props();
 let left=$state(untrack(()=>data.left)),right=$state(untrack(()=>data.right)),days=$state(7),travellers=$state(1),currency=$state('HKD');
 let counts=$state(defaultCounts()),selected=$state<Record<string,string>>({});
 let extraCities=$state<City[]>([]),offerCache=$state<Record<string,Offer[]>>(untrack(()=>data.initialOffers)),loading=$state<Record<string,boolean>>({}),loadErrors=$state<Record<string,string>>({});
 let rates=$state<Record<string,{rate:number;date:string;stale:boolean}>>({}),rateError=$state('');
 let message=$state(''),busy=$state(false),savedId=$state(''),versions=$state<any[]>([]),versionName=$state(''),slot=$state('1');
 let researchingSlug=$state('');
 let adding=$state(false),newCity=$state(''),country=$state(''),localCurrency=$state(''),addingBusy=$state(false),addMessage=$state('');
 const destinations=$derived([...data.destinations,...extraCities]);
 const first=$derived(destinations.find(c=>c.slug===left)!),second=$derived(destinations.find(c=>c.slug===right)!);
 const config=$derived<ComparisonConfig>({left,right,days,travellers,currency:currency.trim().toUpperCase(),counts,selected});
 const validRoutine=$derived.by(()=>{try{validateComparison(config);return true;}catch{return false;}});
 const leftRows=$derived(cityBasket(offerCache[left]||[],left,config)),rightRows=$derived(cityBasket(offerCache[right]||[],right,config));
 const totals=$derived([sumRows(leftRows),sumRows(rightRows)]);
 const shared=$derived(leftRows.filter((row,i)=>row.quantity>0&&row.low!==null&&rightRows[i].low!==null).map(row=>row.id));
 const sameCurrency=$derived(first.currency===second.currency);
 const inferredCurrency=$derived(destinations.find(c=>c.country.toLowerCase()===country.trim().toLowerCase())?.currency||'');
 $effect(()=>{for(const slug of [left,right]){if(!offerCache[slug]&&!loading[slug]){loading[slug]=true;void api('city-offers?city='+encodeURIComponent(slug)).then(result=>{offerCache[slug]=result.offers;loadErrors[slug]='';}).catch(e=>{loadErrors[slug]=(e as Error).message;offerCache[slug]=[];}).finally(()=>loading[slug]=false);}}});
 $effect(()=>{const bases=[first.currency,second.currency],quote=currency.trim().toUpperCase();let cancelled=false;rates={};rateError='';if(!/^[A-Z]{3}$/.test(quote))return;
 const timer=setTimeout(()=>{for(const base of new Set(bases)){if(base==='XXX')continue;void api('exchange-rate?base='+encodeURIComponent(base)+'&quote='+encodeURIComponent(quote)).then(result=>{if(!cancelled)rates[base]=result;}).catch(e=>{if(!cancelled)rateError=(e as Error).message;});}},300);return()=>{cancelled=true;clearTimeout(timer);};});
 $effect(()=>{const slug=researchingSlug;if(!slug)return;let tries=0,stopped=false,inFlight=false;const timer=setInterval(()=>{if(inFlight)return;inFlight=true;void Promise.all([api('city-offers?city='+encodeURIComponent(slug)),api('discovery?city='+encodeURIComponent(slug))]).then(([result,status])=>{if(stopped)return;offerCache[slug]=result.offers;tries++;if(status.sections.filter((s:any)=>s.section!=='overview'&&['needs_review','failed'].includes(s.status)).length===8||tries>=24){researchingSlug='';message='Saved research updated. Any missing comparison prices are shown explicitly.';}}).catch(()=>{tries++;if(tries>=24)researchingSlug='';}).finally(()=>inFlight=false);},5000);return()=>{stopped=true;clearInterval(timer);};});
 onMount(()=>{const profile=readLocal('orach-profile',{currency:'HKD',travellers:1});currency=preferredCurrency(profile.currency);travellers=profile.travellers;if(data.user)void api('comparisons').then(r=>versions=r.comparisons).catch(()=>{});});
 function range(low:number,high:number,code:string){return money(low,code)+(high!==low?' – '+money(high,code):'');}
 function apply(value:any){const c=value.config||value;left=c.left;right=c.right;days=c.days;travellers=c.travellers;currency=preferredCurrency(c.currency);counts={...c.counts};selected={...c.selected};savedId='';message='Saved comparison opened. Current source-listed prices are shown.';}
 async function save(version=false){busy=true;try{const result=await api('comparisons',{config,slot:version?slot:'current',name:version?versionName||'Comparison '+slot:first.name+' & '+second.name});savedId=result.id;versions=(await api('comparisons')).comparisons;message=version?'Comparison version saved.':'Comparison saved to your account.';}catch(e){message=(e as Error).message;}finally{busy=false;}}
 async function subscribe(){busy=true;try{location.href=(await api('checkout',{stayId:''})).url;}catch(e){message=(e as Error).message;}finally{busy=false;}}
 async function manage(){try{location.href=(await api('billing-portal',{})).url;}catch(e){message=(e as Error).message;}}
 async function addCity(){addingBusy=true;addMessage='';try{const cur=(inferredCurrency||localCurrency).trim().toUpperCase();const result=await api('discovery',{city:newCity.trim(),country:country.trim(),currency:cur});if(!result.existing&&result.status!=='needs_review')throw Error('Research has not completed yet. Please retry shortly.');
 const resolved=await api('city-offers?city='+encodeURIComponent(result.slug));if(!destinations.some(c=>c.slug===result.slug))extraCities.push(resolved.city);offerCache[result.slug]=resolved.offers;right=result.slug;researchingSlug=result.queued?result.slug:'';adding=false;message=result.queued?'City selected. Its eight sections are being collected in the background.':'City selected. The free overview is saved. Full section research is available with Plus.';
 }catch(e){addMessage=(e as Error).message;}finally{addingBusy=false;}}
 async function reloadPrices(slug:string){loading[slug]=true;try{offerCache[slug]=(await api('city-offers?city='+encodeURIComponent(slug))).offers;message='Saved city prices refreshed.';}catch(e){message=(e as Error).message;}finally{loading[slug]=false;}}
</script>

<svelte:head><title>Compare city life — Orach</title></svelte:head>
<div class="container comparison-page">
 <div class="page-heading"><div><p class="eyebrow">Your kind of everyday</p><h1>Same routine.<br />A different city.</h1><p>Compare meals, cafés and experiences using prices collected from real sources. Choose how you spend your days; the prices are supplied for you.</p></div><a class="text-link" href="/explore">Browse city fieldnotes →</a></div>
 <section class="comparison-controls panel" aria-label="Choose your comparison">
  <div class="city-pair"><div class="field"><label for="city-a">First city</label><select id="city-a" bind:value={left}>{#each destinations as c}<option value={c.slug}>{c.name}, {c.country}</option>{/each}</select></div><span class="versus" aria-hidden="true">↔</span><div class="field"><label for="city-b">Compare with</label><select id="city-b" bind:value={right}>{#each destinations as c}<option value={c.slug}>{c.name}, {c.country}</option>{/each}</select></div></div>
  <button class="text-link" onclick={()=>adding=!adding}>Can’t find your city? Add it here</button>
  {#if adding}<div class="add-destination"><h3>Add another city</h3>{#if data.user}<div class="form-grid"><div class="field"><label for="new-city">City</label><input id="new-city" bind:value={newCity} maxlength="80" placeholder="For example, Tunis" /></div><div class="field"><label for="new-country">Country or territory</label><input id="new-country" bind:value={country} maxlength="80" placeholder="Type any country" /></div></div>{#if inferredCurrency}<p class="small-text">Local currency: {inferredCurrency}</p>{:else}<div class="field"><label for="new-local-currency">Local currency</label><input id="new-local-currency" bind:value={localCurrency} maxlength="3" placeholder="For example, TND" /></div>{/if}<p class="small-text">The overview is free. Active Plus members also commission all eight sections. You can leave while research continues.</p><button class="button" disabled={addingBusy} onclick={addCity}>{addingBusy?'Adding city…':'Add and compare'}</button>{#if addMessage}<p role="status">{addMessage}</p>{/if}{:else}<p><a href="/sign-up">Create a free account</a> to add a city.</p>{/if}</div>{/if}
  <div class="trip-controls"><div class="field"><label for="days">Days in each city</label><input id="days" type="number" min="1" max="90" bind:value={days} /></div><div class="field"><label for="travellers">Travellers</label><input id="travellers" type="number" min="1" max="20" bind:value={travellers} /></div><div class="field"><label for="familiar">Show conversion in</label><select id="familiar" bind:value={currency}>{#each conversionCurrencies as option}<option value={option.code}>{option.code} — {option.name}</option>{/each}</select></div></div>
 </section>
 {#if left===right}<p class="notice" role="status">Choose two different cities to compare.</p>{/if}
 <section class="routine panel"><div><p class="eyebrow">Make the routine yours</p><h2>What does a good day include?</h2><p class="small-text">Change quantities, then choose the actual offers below. No category budgets to fill in.</p></div><div class="routine-grid">{#each basket as item}<div class="field"><label for={'count-'+item.id}>{item.label}</label><input id={'count-'+item.id} type="number" min="0" max={item.daily?10:100} step="1" bind:value={counts[item.id]} /><small>{item.unit}</small></div>{/each}</div></section>
 <div class="results-heading"><h2>Your researched sample routine</h2><p>{days} days · {travellers} {travellers===1?'traveller':'travellers'} · Accommodation excluded</p></div>
 <section class="quick-compare panel" aria-label="Side-by-side routine costs">
 <table><caption>Same quantities in both cities · selected source-listed base prices</caption><thead><tr><th scope="col">Your routine</th><th scope="col">{first.name}</th><th scope="col">{second.name}</th></tr></thead><tbody>
 {#each leftRows as row,i}{#if row.quantity>0}<tr><th scope="row">{row.label}<small>{row.quantity} across the stay</small></th>{#each [row,rightRows[i]] as cell,j}{@const code=j===0?first.currency:second.currency}<td>{#if validRoutine&&cell.low!==null}{#if rates[code]}<strong>{range(cell.low*rates[code].rate,(cell.high??cell.low)*rates[code].rate,currency.toUpperCase())}</strong><small>{range(cell.low,cell.high??cell.low,code)}</small>{:else}<strong>{range(cell.low,cell.high??cell.low,code)}</strong>{/if}{:else}<span class="missing-price">Not priced</span>{/if}</td>{/each}</tr>{/if}{/each}
 </tbody></table><p class="small-text">Choose or change the actual offers below. Missing rows are excluded from subtotals; accommodation and additional tax/service fees are separate.</p>
 </section>
 <div class="comparison-columns">{#each [first,second] as c,i}
 {@const rows=i===0?leftRows:rightRows}
 {@const summary=totals[i]}
 <section class="city-column" aria-label={c.name+' comparison'}>
 <header><p class="eyebrow">{c.country} · {c.currency}</p><h2>{c.name}</h2><p class="subtotal-label">{summary.missing.length?'Partial priced subtotal':'Priced lifestyle subtotal'}</p><p class="subtotal">{!validRoutine?'Complete your routine':summary.priced?range(summary.low,summary.high,c.currency):'Collecting prices'}</p>
 {#if rates[c.currency]&&summary.priced}<p class="converted">{range(summary.low*rates[c.currency].rate,summary.high*rates[c.currency].rate,currency.toUpperCase())}</p><small>{rates[c.currency].stale?'Last available':'Reference'} rate · {rates[c.currency].date} · Frankfurter</small>{/if}
 <p class="coverage">{summary.priced} of {rows.filter(r=>r.quantity>0).length} selected categories priced{summary.missing.length?' · Missing: '+summary.missing.join(', '):''}</p>
 <a href={'/city/'+c.slug}>Explore {c.name}’s eight sections →</a></header>
 {#if loading[c.slug]}<p role="status" class="column-notice">Loading collected offers…</p>{/if}
 {#if loadErrors[c.slug]}<p role="status" class="column-notice">{loadErrors[c.slug]}</p>{/if}
 {#each rows as row}
 <article class="basket-row" class:muted-row={row.quantity===0}>
 <div class="row-title"><h3>{row.label}</h3><span>{row.quantity} {row.daily?'across your stay':'selected'}</span></div>
 {#if row.quantity>0}
 {#if row.pool.length}<label class="sr-only" for={c.slug+'-'+row.id}>Choose {row.label} in {c.name}</label><select id={c.slug+'-'+row.id} value={row.choice?.id||'none'} onchange={event=>selected[c.slug+':'+row.id]=event.currentTarget.value}><option value="none">Choose an offer / exclude until priced</option>{#each row.pool as offer}<option value={offer.id}>{offer.item} · {money(offer.amount,offer.currency)}{offer.upper!==offer.amount&&offer.upper!==null?'–'+money(offer.upper,offer.currency):''}</option>{/each}</select>{/if}
 {#if row.choice}<p class="selected-price">{range(row.low!,row.high??row.low!,c.currency)} <small>for {row.quantity} × {row.choice.amount}{row.choice.upper!==row.choice.amount&&row.choice.upper!==null?'–'+row.choice.upper:''} {c.currency}</small></p><p class="offer-item">{row.choice.item}<br /><span class="small-text">{row.choice.name}</span></p><details><summary>Source & conditions</summary><p>{row.choice.conditions}</p><p><a href={row.choice.source} target="_blank" rel="noopener noreferrer">{row.choice.sourceTitle} ↗</a></p><small>{row.choice.sourceDate?'Source date: '+row.choice.sourceDate:'The source did not supply a publication date.'} This is a listed offer, not a live quote.</small></details>
 {:else}<p class="missing-price">{row.pool.length?'Choose the exact item above to include it.':'No comparable price collected yet.'}</p><p class="small-text">Excluded from the subtotal. It is not assumed to be free.</p>{/if}
 {:else}<p class="small-text">Not included in your routine.</p>{/if}
 </article>{/each}
 <div class="column-footer"><p>Neighbourhood walks and free outings can be explored in the city profile. Accommodation needs a quote for your dates and is separate.</p><button class="text-link" onclick={()=>reloadPrices(c.slug)}>Refresh saved city prices</button></div>
 </section>{/each}</div>
 <div class="notice methodology"><strong>What these numbers mean</strong><p>They price the particular offers selected above. They are not city averages or a complete cost of living. Listed base prices are used; tax or service fees stated as additional in the source are not added to the subtotal. Menus, ticket restrictions and availability can change. Optional grocery packs and garments are specific products, not equivalent baskets.</p><p>For a like-for-like view, both cities currently have prices for: {shared.length?basket.filter(b=>shared.includes(b.id)).map(b=>b.label).join(', '):'no shared selected categories yet'}. Compare those rows; partial subtotals with different coverage are not a fair overall ranking.</p>{#if rateError}<p role="status">{rateError}</p>{/if}</div>
 <section class="save-panel panel"><div><h2>Keep this comparison</h2><p>Your current comparison saves free. Plus adds three named versions, a printable source-backed summary and research for missing cities.</p></div>
 {#if data.user}<button class="button" disabled={busy||!validRoutine} onclick={()=>save()}>{busy?'Saving…':'Save current comparison free'}</button>{:else}<a class="button" href="/sign-up">Create a free account to save</a>{/if}
 {#if versions.length}<div class="saved-list">{#each versions as version}<button class="button secondary small" onclick={()=>apply(version.data)}>{version.name}</button>{/each}</div>{/if}
 {#if data.member}<div class="form-grid"><div class="field"><label for="version-name">Version name</label><input id="version-name" bind:value={versionName} maxlength="80" placeholder="For example, more cultural outings" /></div><div class="field"><label for="version-slot">Saved version</label><select id="version-slot" bind:value={slot}><option value="1">Version 1</option><option value="2">Version 2</option><option value="3">Version 3</option></select></div></div><div class="save-actions"><button class="button secondary" disabled={busy||!validRoutine} onclick={()=>save(true)}>Save named version</button>{#if savedId}<a class="button secondary" href={'/api/comparisons/summary?id='+savedId}>Printable summary / PDF</a>{/if}<button class="text-link" onclick={manage}>Manage membership</button></div>
 {:else}<p class="small-text">Orach Plus · US$7.99/month, renewing until cancelled.</p>{#if data.user&&data.billingAvailable}<button class="button secondary" disabled={busy} onclick={subscribe}>Subscribe to Orach Plus</button>{/if}{/if}
 {#if message}<p role="status" class="notice info">{message}</p>{/if}
 </section>
 <p class="legacy-link"><a href="/saved-plans">Open previous saved plans</a> · Existing plans remain available.</p>
</div>

<style>
 .quick-compare{margin-bottom:24px;overflow-x:auto}.quick-compare table{width:100%;border-collapse:collapse;table-layout:fixed}.quick-compare caption{text-align:left;font-size:12px;color:var(--muted);margin-bottom:18px}.quick-compare th,.quick-compare td{text-align:left;padding:18px 12px;border-bottom:1px solid var(--line);vertical-align:top;overflow-wrap:anywhere}.quick-compare thead th{font:600 20px Manrope,sans-serif}.quick-compare th:first-child{width:30%}.quick-compare tbody th{font-size:13px;font-weight:500}.quick-compare small{display:block;font-size:11px;color:var(--muted);margin-top:7px}.quick-compare td strong{font-size:16px}.quick-compare>p{margin-top:18px}
 .comparison-page{padding-top:35px;padding-bottom:70px}.comparison-controls{display:grid;gap:20px}.comparison-controls .field,.routine .field,.save-panel .field{margin:0}.city-pair{display:grid;grid-template-columns:1fr auto 1fr;gap:18px;align-items:end}.versus{padding:15px 0;color:var(--muted);font-size:24px}.trip-controls{display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px}.add-destination{padding:22px;background:#f3f6ee;border-radius:12px;display:grid;gap:18px}.add-destination .field{margin:0}.routine{margin:24px 0;display:grid;gap:22px}.routine h2{font-size:25px;margin-bottom:8px}.routine-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.routine small{display:block;color:var(--muted);font-size:11px;margin-top:7px}.results-heading{display:flex;justify-content:space-between;gap:18px;align-items:end;margin:40px 0 22px}.results-heading h2{font-size:28px}.results-heading p{font-size:13px;color:var(--muted)}.comparison-columns{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}.city-column{border:1px solid var(--line);border-radius:18px;background:white;overflow:hidden;min-width:0}.city-column header{padding:28px;background:#e9efdf;min-height:275px}.city-column:nth-child(2) header{background:#e2edf0}.city-column h2{font-size:36px;margin:10px 0 24px}.subtotal-label{font-size:12px;color:var(--muted)}.subtotal{font:600 32px Manrope,sans-serif;letter-spacing:-1px;margin:8px 0}.converted{font-size:19px;margin:5px 0}.city-column header small{font-size:10px;color:var(--muted)}.coverage{font-size:12px;line-height:1.65;margin:16px 0}.city-column header a{font-size:13px;font-weight:600}.basket-row{padding:25px 28px;border-bottom:1px solid var(--line);min-height:260px}.row-title{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}.row-title h3{font-size:17px}.row-title span{font-size:10px;color:var(--muted)}.basket-row select{width:100%;max-width:100%;box-sizing:border-box;background:#f8faf7;border:1px solid var(--line);border-radius:8px;padding:12px;font:13px 'DM Sans',sans-serif;color:var(--ink)}.selected-price{font-size:21px;font-weight:600;margin:18px 0 9px}.selected-price small{display:block;font-size:11px;color:var(--muted);font-weight:400;margin-top:7px}.offer-item{font-size:13px;line-height:1.65;margin-bottom:14px}.basket-row details{font-size:12px;line-height:1.75}.basket-row details p{white-space:pre-wrap;margin:10px 0;overflow-wrap:anywhere}.basket-row summary{cursor:pointer;text-decoration:underline;text-underline-offset:4px}.basket-row details small{color:var(--muted)}.missing-price{font-weight:600;margin-bottom:9px}.muted-row{min-height:110px;background:#fbfcfa}.column-footer{padding:24px 28px;font-size:12px;color:var(--muted);line-height:1.7}.column-footer button{margin-top:14px}.column-notice{padding:15px 28px}.methodology{margin:24px 0;line-height:1.8}.methodology p{margin-top:10px}.save-panel{display:grid;gap:20px}.save-panel h2{font-size:27px;margin-bottom:10px}.save-panel p{line-height:1.7}.save-actions,.saved-list{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.legacy-link{font-size:12px;color:var(--muted);margin-top:24px}.text-link{background:none;border:0;font:inherit;text-align:left;cursor:pointer;padding:0;justify-self:start}
 @media(max-width:700px){.city-pair{grid-template-columns:1fr}.versus{display:none}.trip-controls{gap:12px;grid-template-columns:1fr 1fr}.trip-controls .field:last-child{grid-column:1/-1}.routine-grid{grid-template-columns:1fr 1fr}.results-heading{display:block}.results-heading p{margin-top:12px}.comparison-columns{grid-template-columns:1fr}.city-column header{min-height:0}.basket-row{min-height:0;padding:22px}.subtotal{font-size:29px}.save-actions .button{width:100%}}
</style>
